import { sp } from 'cc';

/**
 * 已經警告過的 (呼叫端, 動畫名) 組合。
 *
 * spine 動畫通常掛在每幀或每次轉輪都會走到的路徑上，不去重的話一個缺漏的
 * 動畫名就會把 console 洗掉，反而看不到別的訊息。
 */
const warnedKeys = new Set<string>();

/**
 * 印一次帶前綴的警告，同一個 key 之後就不再印。
 *
 * @param key 去重用的鍵。
 * @param message 訊息本文。
 * @param err 原始例外。
 */
function warnOnce(key: string, message: string, err: unknown): void {
    if (warnedKeys.has(key)) return;
    warnedKeys.add(key);
    console.warn(message, err);
}

/**
 * 切換 spine 動畫，動畫名不存在時吞掉例外並警告一次。
 *
 * spine 資產是美術分批交付的，缺一支動畫時 `setAnimation()` 會丟例外。
 * 這裡刻意不讓例外往上冒——報獎與轉輪的流程都不該因為少一支動畫就整條中斷——
 * 但一定要留下痕跡，否則症狀只剩「圖不會動」，跟節點沒開、資源沒載完全分不出來。
 *
 * @param skeleton 目標 spine。
 * @param anim 動畫名稱。
 * @param loop 是否循環播放。
 * @param tag 呼叫端識別字，只用在警告訊息上。
 * @returns 成功切換時回 true，動畫不存在時回 false。
 */
export function trySetAnimation(skeleton: sp.Skeleton, anim: string, loop: boolean, tag: string): boolean {
    try {
        skeleton.setAnimation(0, anim, loop);
        return true;
    } catch (err) {
        warnOnce(`${tag}|${anim}`, `[SpineSafe] ${tag}：spine 沒有動畫 "${anim}"，略過`, err);
        return false;
    }
}

/**
 * 把 spine 的當前動畫清空，資產還沒載好時吞掉例外並警告一次。
 *
 * 用在「先關掉再依狀態決定要播什麼」的初始化路徑上，理由同 {@link trySetAnimation}。
 *
 * @param skeleton 目標 spine。
 * @param tag 呼叫端識別字，只用在警告訊息上。
 */
export function tryClearAnimation(skeleton: sp.Skeleton, tag: string): void {
    try {
        skeleton.animation = '';
    } catch (err) {
        warnOnce(`${tag}|<clear>`, `[SpineSafe] ${tag}：清空 spine 動畫失敗，略過`, err);
    }
}
